pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val) internal {
        bool revertedBefore;
        try c.SetMinSum(_val) { revertedBefore = false; } catch { revertedBefore = true; }
        vm.assume(!revertedBefore);
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedAfter;
        try c.SetMinSum(_val) { revertedAfter = false; } catch { revertedAfter = true; }
        assertTrue(revertedAfter && minSumAfter == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
